// MANUAL FILE (not generated by HARIA). Safe across regenerations.
//
// Utilidades compartidas por las páginas migradas desde WikiGames.HTML:
// usuario actual, árbol de categorías y subida de la imagen de un videojuego.
using System.Globalization;
using System.Security.Claims;
using WikiGames.Domain.Entities;
using WikiGames.Web.Models.Usuarios;
using WikiGames.Web.ViewModels.Paginas;

namespace WikiGames.Web.Utils.Paginas;

public static class WikiGamesPaginas
{
    private static readonly StringComparer EsComparer = StringComparer.Create(new CultureInfo("es-ES"), ignoreCase: true);

    /// <summary>Id del Usuario autenticado según la cookie (escrita por el servidor), o null si es anónimo.</summary>
    public static int? UsuarioActualId(ClaimsPrincipal user)
    {
        if (user.Identity?.IsAuthenticated != true) return null;
        var model = user.AsUsuarioModel();
        if (model is not null && model.Id > 0) return model.Id;
        return int.TryParse(user.FindFirstValue(ClaimTypes.Name), out var id) ? id : null;
    }

    /// <summary>Categorías ordenadas en árbol: cada raíz seguida de sus hijas (recursivo), con su nivel.</summary>
    public static List<CategoriaOpcionViewModel> ArbolCategorias(IEnumerable<Categoria> categorias)
    {
        var all = categorias.ToList();
        var result = new List<CategoriaOpcionViewModel>();
        void Add(Categoria c, int nivel)
        {
            result.Add(new CategoriaOpcionViewModel { Id = c.Id, Name = c.Name, PadreId = c.Padre?.Id, PadreName = c.Padre?.Name, Nivel = nivel });
            foreach (var hija in all.Where(h => h.Padre?.Id == c.Id).OrderBy(h => h.Name, EsComparer)) Add(hija, nivel + 1);
        }
        foreach (var raiz in all.Where(c => c.Padre is null).OrderBy(c => c.Name, EsComparer)) Add(raiz, 0);
        return result;
    }

    /// <summary>Una categoría incluye también a todas sus subcategorías.</summary>
    public static HashSet<int> ConDescendientes(IEnumerable<Categoria> categorias, int id)
    {
        var all = categorias.ToList();
        var result = new HashSet<int> { id };
        var pendientes = new Queue<int>(result);
        while (pendientes.Count > 0)
        {
            var actual = pendientes.Dequeue();
            foreach (var hija in all.Where(c => c.Padre?.Id == actual))
                if (result.Add(hija.Id)) pendientes.Enqueue(hija.Id);
        }
        return result;
    }

    // ------------------------------------------------------------------ Imágenes

    /// <summary>Comprueba tamaño, extensión, tipo y firma (PNG/JPEG) según HariaWeb:Files. Devuelve el error o null.</summary>
    public static string? ValidarImagen(IFormFile file, IConfiguration configuration)
    {
        var section = configuration.GetSection("HariaWeb:Files");
        var maxBytes = section.GetValue<long?>("MaxBytes") ?? 5 * 1024 * 1024;
        var extensions = section.GetSection("AllowedExtensions").Get<string[]>() ?? [".png", ".jpg", ".jpeg"];
        var contentTypes = section.GetSection("AllowedContentTypes").Get<string[]>() ?? ["image/png", "image/jpeg"];

        if (file.Length == 0) return "La imagen está vacía.";
        if (file.Length > maxBytes) return $"La imagen no puede superar {maxBytes / (1024 * 1024)} MB.";
        var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
        if (!extensions.Contains(ext, StringComparer.OrdinalIgnoreCase) || !contentTypes.Contains(file.ContentType, StringComparer.OrdinalIgnoreCase))
            return "Solo se admiten imágenes PNG o JPEG.";

        Span<byte> header = stackalloc byte[8];
        using var stream = file.OpenReadStream();
        var read = stream.Read(header);
        var isPng = read >= 8 && header[..8].SequenceEqual(new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A });
        var isJpeg = read >= 3 && header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF;
        return isPng || isJpeg ? null : "El archivo no es una imagen PNG o JPEG válida.";
    }

    /// <summary>
    /// Guarda la imagen en wwwroot/{UploadRoot}/{Clase}/{Atributo}/{Id}/ (convención del README de HARIA)
    /// con un nombre generado por el servidor, y devuelve su ruta pública ("/uploads/...").
    /// </summary>
    public static async Task<string> GuardarImagenAsync(IFormFile file, IWebHostEnvironment environment, IConfiguration configuration,
        string clase, string atributo, int id, CancellationToken cancellationToken = default)
    {
        var uploadRoot = configuration.GetValue<string>("HariaWeb:Files:UploadRoot") ?? "uploads";
        var ext = Path.GetExtension(file.FileName).ToLowerInvariant() == ".png" ? ".png" : ".jpg";
        var relativeDir = Path.Combine(uploadRoot, clase, atributo, id.ToString(CultureInfo.InvariantCulture));
        var physicalDir = Path.Combine(environment.WebRootPath, relativeDir);
        Directory.CreateDirectory(physicalDir);
        var fileName = Guid.NewGuid().ToString("N") + ext;
        await using (var target = File.Create(Path.Combine(physicalDir, fileName)))
            await file.CopyToAsync(target, cancellationToken);
        return "/" + Path.Combine(relativeDir, fileName).Replace('\\', '/');
    }
}
